const supportTickets=[
 {id:'aa2c7500-1111-4a22-8b33-123456789001',requester_name:'Tendai Moyo',requester_role:'shop_owner',category:'billing',subject:'Extend shop subscription',message:'Please extend our current plan by 30 days.',priority:'normal',status:'pending',created_at:'2026-11-20T07:40:00Z'},
 {id:'aa2c7500-1111-4a22-8b33-123456789002',requester_name:'Rudo Ncube',requester_role:'public',category:'complaint',subject:'Incorrect product availability',message:'A listed item was unavailable when I arrived at the shop.',priority:'high',status:'in_progress',created_at:'2026-11-20T06:20:00Z'},
 {id:'aa2c7500-1111-4a22-8b33-123456789003',requester_name:'Tatenda Pedals',requester_role:'courier',category:'technical',subject:'Location did not refresh',message:'Location refreshed after restarting the app.',priority:'normal',status:'attended',created_at:'2026-11-19T14:10:00Z',attended_at:'2026-11-19T15:05:00Z'}
];
const subscriptionRequests=[{id:'bb2c7500-1111-4a22-8b33-123456789001',shop:'Mbare Market Fresh',type:'extend',days:30,note:'Extend before holiday trading period',status:'pending'}];
const profileDetails=new Map(profiles.map((title,index)=>[title,{id:title.toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),title,icon:'layout-grid',description:'Public business discovery profile.',enabled:true,order:index+1}]));
let productionAdminHydrated=false;
function safeAdminText(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function sanitizeSupportData(){for(const t of supportTickets){if(t._safe)continue;for(const key of ['requester_name','subject','message','admin_note'])t[key]=safeAdminText(t[key]);t._safe=true}for(const r of subscriptionRequests){if(r._safe)continue;for(const key of ['shop','type','note'])r[key]=safeAdminText(r[key]);r._safe=true}}

function renderBulkSubscriptions(){return `<section class="panel"><div class="panel-head"><div><h2>Set subscriptions in bulk</h2><p>Apply one plan to every shop, every courier, or both groups in a single transaction.</p></div><span class="status">Admin only</span></div><form id="bulkSubscriptionForm" class="bulk-subscription"><label>Apply to<select name="scope"><option value="all">All shops and couriers</option><option value="shops">All shops</option><option value="couriers">All couriers</option></select></label><label>Shop amount (USD)<input name="shopAmount" type="number" min="0" step=".01" value="25" required></label><label>Courier amount (USD)<input name="courierAmount" type="number" min="0" step=".01" value="15" required></label><label>Duration days<input name="duration" type="number" min="1" value="30" required></label><label>Trial days<input name="trial" type="number" min="0" value="0"></label><label>Status<select name="status"><option value="active">Active</option><option value="trial">Trial</option><option value="past_due">Past due</option><option value="suspended">Suspended</option><option value="cancelled">Cancelled</option></select></label><button class="primary">Apply plan</button></form></section>`}

renderSubscriptions=function(){adminRefreshProductionData();$('#adminContent').innerHTML=`${renderBulkSubscriptions()}<section class="panel" style="margin-top:12px"><div class="panel-head"><div><h2>Individual shop subscriptions</h2><p>Fine-tune amount, duration, trial and access for one shop.</p></div></div><form class="subscription-form" id="subscriptionForm"><select name="shop" aria-label="Shop">${businesses.map(b=>`<option>${b[0]}</option>`).join('')}</select><input name="amount" type="number" min="0" step="0.01" value="25" required><input name="duration" type="number" min="1" value="30" required><input name="trial" type="number" min="0" value="0"><select name="status"><option value="active">Active</option><option value="trial">Trial</option><option value="past_due">Past due</option><option value="suspended">Suspended</option><option value="cancelled">Cancelled</option></select><button class="primary">Save shop plan</button></form>${table(['Shop','Amount','Duration','Trial','Status','Access until','Action'],subscriptions.map((s,i)=>`<tr><td><strong>${s.shop}</strong></td><td>US$ ${Number(s.amount).toFixed(2)}</td><td>${s.duration} days</td><td>${s.trial?s.trial+' days':'—'}</td><td><span class="status ${s.status==='active'?'active':s.status==='trial'?'approved':'suspended'}">${s.status.replace('_',' ')}</span></td><td>${s.ends}</td><td><button class="edit" data-edit-subscription="${i}">Edit</button></td></tr>`))}</section>`;icons()};

renderProfiles=function(){adminRefreshProductionData();$('#adminContent').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Business profile catalogue</h2><p>Add, edit, disable or delete discovery profiles. Linked profiles must be reassigned before deletion.</p></div><span class="status">${profiles.length} profiles</span></div><form id="profileCreateForm" class="profile-create-form"><label>Profile ID<input name="id" pattern="[a-z][a-z0-9-]{1,48}" placeholder="e.g. agriculture" required></label><label>Display title<input name="title" required></label><label>Lucide icon<input name="icon" value="store" required></label><label class="wide">Description<textarea name="description" required></textarea></label><label>Display order<input name="order" type="number" min="0" value="20"></label><button class="primary">Add profile</button></form><div class="profile-admin-grid">${profiles.map(title=>{const p=profileDetails.get(title);return `<article class="profile-admin-card"><header><span><i data-lucide="${p.icon}"></i></span><span class="status ${p.enabled?'active':'suspended'}">${p.enabled?'enabled':'disabled'}</span></header><h3>${p.title}</h3><small><code>${p.id}</code> • position ${p.order}</small><p>${p.description}</p><footer><button data-edit-profile="${p.id}">Edit</button><button data-toggle-profile="${p.id}">${p.enabled?'Disable':'Enable'}</button><button class="danger" data-delete-profile="${p.id}">Delete</button></footer></article>`}).join('')}</div></section>`;icons()};

function renderModeration(){adminRefreshProductionData();sanitizeSupportData();const pendingTickets=supportTickets.filter(t=>t.status!=='attended'),attended=supportTickets.filter(t=>t.status==='attended').sort((a,b)=>String(b.attended_at).localeCompare(String(a.attended_at))).slice(0,20);$('#adminContent').innerHTML=`<div class="metric-grid support-metrics">${metric('inbox','Pending tickets',pendingTickets.length)}${metric('messages-square','In progress',supportTickets.filter(t=>t.status==='in_progress').length)}${metric('circle-check','Attended retained',attended.length+'/20')}${metric('file-clock','Subscription requests',subscriptionRequests.filter(r=>r.status==='pending').length)}</div><div class="retention-note"><strong>Storage policy:</strong> pending tickets remain until handled; only the latest 20 attended tickets are retained.</div><div class="split-support"><section class="panel"><div class="panel-head"><div><h2>Support hub</h2><p>Requests, complaints, billing and technical support.</p></div></div><div class="ticket-list">${[...pendingTickets,...attended].map(t=>`<article class="support-ticket ${t.status}"><span><i data-lucide="${t.category==='complaint'?'message-circle-warning':t.category==='billing'?'badge-dollar-sign':'life-buoy'}"></i></span><div><span class="status ${t.status==='attended'?'active':t.priority==='high'||t.priority==='urgent'?'suspended':'approved'}">${t.status.replace('_',' ')} • ${t.priority}</span><h3>${t.subject}</h3><small>${t.requester_name} • ${t.requester_role.replace('_',' ')} • ${new Date(t.created_at).toLocaleString()}</small><p>${t.message}</p>${t.admin_note?`<small><strong>Admin note:</strong> ${t.admin_note}</small>`:''}</div><aside>${t.status==='pending'?`<button data-ticket-progress="${t.id}">Start</button>`:''}${t.status!=='attended'?`<button class="primary" data-ticket-attended="${t.id}">Mark attended</button>`:'<span class="status active">Closed</span>'}</aside></article>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>Subscription requests</h2><p>Owner renew, extend and cancel requests.</p></div></div><div class="request-stack">${subscriptionRequests.filter(r=>r.status==='pending').map(r=>`<article class="request-card"><span class="status approved">${r.type}</span><h4>${r.shop}</h4><p>${r.days?`${r.days} days • `:''}${r.note||'No note supplied'}</p><footer><button data-sub-request="${r.id}" data-decision="approved">Approve</button><button class="danger" data-sub-request="${r.id}" data-decision="rejected">Reject</button></footer></article>`).join('')||'<p>No subscription requests are pending.</p>'}</div></section></div>`;icons()}

renderAudit=function(){adminRefreshProductionData();const retained=audit.slice(0,20);$('#adminContent').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Audit trail</h2><p>The latest 20 platform security and transaction events are retained.</p></div><span class="status">${retained.length}/20 retained</span></div><div class="retention-note">Older audit events are removed automatically after every insert to cap storage.</div>${table(['Event','Actor','Entity','Timestamp'],retained.map(a=>`<tr><td><strong>${a[0]}</strong></td><td>${a[1]}</td><td><code>${a[2]}</code></td><td>${a[3]}</td></tr>`))}</section>`};

const originalRenderGeneric=renderGeneric;
renderGeneric=function(view){if(view==='moderation')return renderModeration();return originalRenderGeneric(view)};

async function adminRefreshProductionData(){if(productionAdminHydrated||!window.zwconnectSupabase||!navigator.onLine)return;productionAdminHydrated=true;try{const db=window.zwconnectSupabase,[tickets,profileRows,auditRows,requestRows]=await Promise.all([db.from('support_tickets').select('*').order('created_at',{ascending:false}),db.from('business_profiles').select('*').order('display_order'),db.from('audit_events').select('action,entity_type,created_at,actor_id').order('created_at',{ascending:false}).limit(20),db.from('subscription_requests').select('id,request_type,requested_days,owner_note,status,shops(name)').eq('status','pending').order('created_at',{ascending:false})]);if(!tickets.error){supportTickets.splice(0,supportTickets.length,...(tickets.data||[]))}if(!profileRows.error){profiles.splice(0,profiles.length);profileDetails.clear();for(const p of profileRows.data||[]){profiles.push(p.title);profileDetails.set(p.title,{id:p.id,title:p.title,icon:p.icon,description:p.description,enabled:p.enabled,order:p.display_order})}}if(!auditRows.error){audit.splice(0,audit.length,...(auditRows.data||[]).map(a=>[a.action,a.actor_id?.slice(0,8)||'System',a.entity_type,new Date(a.created_at).toLocaleString()]))}if(!requestRows.error){subscriptionRequests.splice(0,subscriptionRequests.length,...(requestRows.data||[]).map(r=>({id:r.id,shop:r.shops?.name||'Shop',type:r.request_type,days:r.requested_days,note:r.owner_note,status:r.status})))}}catch(error){toast(error.message||'Could not refresh production admin data','cloud-off')}finally{if(['subscriptions','profiles','moderation','audit'].includes(currentView))render()}}

document.addEventListener('submit',e=>{if(e.target.id==='bulkSubscriptionForm'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),scope=d.scope,record={scope,applyShops:scope==='all'||scope==='shops',applyCouriers:scope==='all'||scope==='couriers',shopAmount:Number(d.shopAmount),courierAmount:Number(d.courierAmount),duration:Number(d.duration),trial:Number(d.trial||0),status:d.status};if(record.applyShops)subscriptions.forEach(s=>Object.assign(s,{amount:record.shopAmount,duration:record.duration,trial:record.trial,status:record.status,ends:`${record.duration} days from activation`}));if(record.applyCouriers)couriers.forEach(c=>Object.assign(c,{amount:record.courierAmount,duration:record.duration,trial:record.trial,subscription:record.status}));queueAdminAction('subscription.bulk_update',record,`Bulk plan applied to ${scope}`);renderSubscriptions()}if(e.target.id==='profileCreateForm'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),title=d.title.trim(),profile={id:d.id.trim(),title,icon:d.icon.trim(),description:d.description.trim(),enabled:true,order:Number(d.order)};if(profileDetails.has(title)){toast('A profile with this title already exists','shield-alert');return}profiles.push(title);profileDetails.set(title,profile);queueAdminAction('profile.create',profile,`${title} profile added`);renderProfiles()}});

document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-profile]');if(edit){const entry=[...profileDetails.values()].find(p=>p.id===edit.dataset.editProfile),title=prompt('Profile title',entry.title),icon=title&&prompt('Lucide icon',entry.icon),description=icon&&prompt('Description',entry.description);if(title&&icon&&description){const index=profiles.indexOf(entry.title);profiles[index]=title.trim();profileDetails.delete(entry.title);Object.assign(entry,{title:title.trim(),icon:icon.trim(),description:description.trim()});profileDetails.set(entry.title,entry);queueAdminAction('profile.update',entry,`${entry.title} profile updated`);renderProfiles()}}const toggle=e.target.closest('[data-toggle-profile]');if(toggle){const entry=[...profileDetails.values()].find(p=>p.id===toggle.dataset.toggleProfile);entry.enabled=!entry.enabled;queueAdminAction('profile.update',entry,`${entry.title} ${entry.enabled?'enabled':'disabled'}`);renderProfiles()}const remove=e.target.closest('[data-delete-profile]');if(remove){const entry=[...profileDetails.values()].find(p=>p.id===remove.dataset.deleteProfile);if(confirm(`Delete ${entry.title}? Linked shops must be reassigned first.`)){queueAdminAction('profile.delete',{id:entry.id},`${entry.title} deletion requested`);profiles.splice(profiles.indexOf(entry.title),1);profileDetails.delete(entry.title);renderProfiles()}}const progress=e.target.closest('[data-ticket-progress]');if(progress)updateTicket(progress.dataset.ticketProgress,'in_progress');const attended=e.target.closest('[data-ticket-attended]');if(attended)updateTicket(attended.dataset.ticketAttended,'attended');const request=e.target.closest('[data-sub-request]');if(request){const item=subscriptionRequests.find(r=>r.id===request.dataset.subRequest),decision=request.dataset.decision,note=prompt('Admin note visible to the owner',decision==='approved'?'Request approved.':'Request could not be approved.');if(note){item.status=decision;queueAdminAction('subscription_request.review',{requestId:item.id,approve:decision==='approved',note},`${item.shop} request ${decision}`);renderModeration()}}});

function updateTicket(id,status){const ticket=supportTickets.find(t=>t.id===id),note=prompt('Admin response note',status==='attended'?'Issue resolved and customer notified.':'Ticket assigned for review.');if(!note)return;ticket.status=status;ticket.admin_note=note;ticket._safe=false;ticket.attended_at=status==='attended'?new Date().toISOString():null;queueAdminAction('support_ticket.update',{ticketId:id,status,note,priority:ticket.priority},`Ticket marked ${status.replace('_',' ')}`);renderModeration()}
